import React, { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { Agent, AgentStatus, ToolCall } from '../types';

const INITIAL_AGENTS: Agent[] = [
  { id: 'agent-1', name: 'Research Agent', status: 'idle', provider: { name: 'OpenAI', status: 'healthy', latency: 45 }, subAgents: [] },
  { id: 'agent-2', name: 'Code Generator', status: 'running', provider: { name: 'Anthropic', status: 'healthy', latency: 120 }, subAgents: [] },
  { id: 'agent-3', name: 'Data Parser', status: 'error', provider: { name: 'Local', status: 'degraded', latency: 300 }, subAgents: [] },
];

interface AgentContextType {
  agents: Agent[];
  toolCalls: ToolCall[];
  isLoading: boolean;
  updateAgentStatus: (id: string, status: AgentStatus) => void;
  simulateToolCall: (agentId: string, toolName: string, args: Record<string, unknown>) => void;
}

const AgentContext = createContext<AgentContextType | undefined>(undefined);

export const AgentProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [agents, setAgents] = useState<Agent[]>(INITIAL_AGENTS);
  const [toolCalls, setToolCalls] = useState<ToolCall[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 600);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (isLoading) return;
    const interval = setInterval(() => {
      setAgents(prev => prev.map(agent => {
        if (Math.random() > 0.7) {
          const statuses: AgentStatus[] = ['idle', 'running', 'processing', 'waiting', 'completed', 'error'];
          return { ...agent, status: statuses[Math.floor(Math.random() * statuses.length)] };
        }
        return agent;
      }));
    }, 2000);
    return () => clearInterval(interval);
  }, [isLoading]);

  const updateAgentStatus = useCallback((id: string, status: AgentStatus) => {
    setAgents(prev => prev.map(a => a.id === id ? { ...a, status } : a));
  }, []);

  const simulateToolCall = useCallback((agentId: string, toolName: string, args: Record<string, unknown>) => {
    const newCall: ToolCall = {
      id: `tc-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      agentId,
      tool: toolName,
      args: JSON.stringify(args),
      status: 'pending',
      timestamp: new Date().toISOString()
    };
    setToolCalls(prev => [newCall, ...prev].slice(0, 50));

    setTimeout(() => {
      setToolCalls(prev => prev.map(t => t.id === newCall.id ? { ...t, status: 'completed', output: 'Mock response generated.' } : t));
    }, 1500);
  }, []);

  return (
    <AgentContext.Provider value={{ agents, toolCalls, isLoading, updateAgentStatus, simulateToolCall }}>
      {children}
    </AgentContext.Provider>
  );
};

export const useAgentContext = (): AgentContextType => {
  const ctx = useContext(AgentContext);
  if (!ctx) throw new Error('useAgentContext must be used inside AgentProvider');
  return ctx;
};"}

